    String artifactName(String name){return name+(uiLocale.isEmpty()?"":"-"+uiLocale);}
    String phoneLocaleTags(){if(Build.VERSION.SDK_INT>=33){android.app.LocaleManager manager=getTargetContext().getSystemService(android.app.LocaleManager.class);check(manager!=null,"System LocaleManager unavailable");return manager.getSystemLocales().toLanguageTags();}return Resources.getSystem().getConfiguration().getLocales().toLanguageTags();}
    void configureAppLocale()throws Exception{
        systemLocaleTags=phoneLocaleTags();
        if(uiLocale.isEmpty())return;
        check(uiLocale.equals("zh")||uiLocale.equals("en"),"uiLocale must be zh or en");
        check(Build.VERSION.SDK_INT>=33,"uiLocale requires Android 13+ app-scoped LocaleManager; global locale is never changed");
        appLocaleManager=getTargetContext().getSystemService(android.app.LocaleManager.class);
        check(appLocaleManager!=null,"App LocaleManager unavailable");originalAppLocales=appLocaleManager.getApplicationLocales();appLocaleSnapshot=true;
        report.put("uiLocale",uiLocale).put("previousApplicationLocales",originalAppLocales.toLanguageTags()).put("systemLocalesBefore",systemLocaleTags);
        appLocaleManager.setApplicationLocales(LocaleList.forLanguageTags(uiLocale));waitForIdleSync();
    }
    void restoreAppLocale()throws Exception{
        if(!appLocaleSnapshot)return;
        // Close the tested Activity first: a locale-driven recreation must not write after exact-byte restoration.
        if(activity!=null){onMain(()->{activity.finish();return null;});waitForIdleSync();for(int i=0;i<100&&!activity.isDestroyed();i++)sleep(20);check(activity.isDestroyed(),"Activity did not finish before locale restoration");}
        appLocaleManager.setApplicationLocales(originalAppLocales);waitForIdleSync();
        check(originalAppLocales.equals(appLocaleManager.getApplicationLocales()),"Previous application locales not restored");
        check(systemLocaleTags.equals(phoneLocaleTags()),"Global phone locales changed");
        report.put("applicationLocalesRestored",true).put("systemLocalesUnchanged",true);
    }
