    byte[] bytes(File file)throws Exception{try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);return out.toByteArray();}}
    void snapshotCloudDraft()throws Exception{
        cloudDraftFile=new File(getTargetContext().getFilesDir(),"system-cloud-draft.json");
        check(!cloudDraftFile.exists()||cloudDraftFile.isFile(),"Cloud draft path is not a regular file");
        cloudDraftExisted=cloudDraftFile.isFile();originalCloudDraftBytes=cloudDraftExisted?bytes(cloudDraftFile):null;cloudDraftSnapshot=true;
    }
    void restoreCloudDraft()throws Exception{
        if(!cloudDraftSnapshot)return;
        File expected=new File(getTargetContext().getFilesDir(),"system-cloud-draft.json");
        check(cloudDraftFile.getCanonicalFile().equals(expected.getCanonicalFile()),"Unexpected cloud draft restore target");
        if(cloudDraftExisted){if(cloudDraftFile.isFile()&&Arrays.equals(bytes(cloudDraftFile),originalCloudDraftBytes))return;try(FileOutputStream out=new FileOutputStream(cloudDraftFile)){out.write(originalCloudDraftBytes);out.getFD().sync();}check(Arrays.equals(bytes(cloudDraftFile),originalCloudDraftBytes),"Original cloud draft bytes not restored");}
        else if(cloudDraftFile.exists())check(cloudDraftFile.isFile()&&cloudDraftFile.delete(),"New test cloud draft could not be removed");
    }
    void snapshotNativeDraft()throws Exception{
        nativeDraftFile=new File(getTargetContext().getFilesDir(),"native-draft.json");
        check(!nativeDraftFile.exists()||nativeDraftFile.isFile(),"Native draft path is not a regular file");
        nativeDraftExisted=nativeDraftFile.isFile();originalNativeDraftBytes=nativeDraftExisted?bytes(nativeDraftFile):null;nativeDraftSnapshot=true;
    }
    void restoreNativeDraft()throws Exception{
        if(!nativeDraftSnapshot)return;
        File expected=new File(getTargetContext().getFilesDir(),"native-draft.json");
        check(nativeDraftFile.getCanonicalFile().equals(expected.getCanonicalFile()),"Unexpected native draft restore target");
        if(nativeDraftExisted){if(nativeDraftFile.isFile()&&Arrays.equals(bytes(nativeDraftFile),originalNativeDraftBytes))return;try(FileOutputStream out=new FileOutputStream(nativeDraftFile)){out.write(originalNativeDraftBytes);out.getFD().sync();}check(Arrays.equals(bytes(nativeDraftFile),originalNativeDraftBytes),"Original native draft bytes not restored");}
        else if(nativeDraftFile.exists())check(nativeDraftFile.isFile()&&nativeDraftFile.delete(),"New test native draft could not be removed");
    }
    JSONObject cloudDraft()throws Exception{return new JSONObject(new String(bytes(cloudDraftFile),"UTF-8"));}
    ListView firstList(View root){if(root instanceof ListView)return (ListView)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){ListView list=firstList(((ViewGroup)root).getChildAt(i));if(list!=null)return list;}return null;}
